// Connectors for the 100 databases. Each one calls a real, public source at request time.
// Configuration per dataset lives in datasets.json (generated by tools/inventory/build.py).
import { XMLParser } from 'fast-xml-parser';
import { HttpError } from './core.js';

const UA = process.env.ZF_SOURCE_USER_AGENT || 'CollectiveAI-ZenFlowMarketplace/1.0 (+https://zenflow-marketplace.vercel.app)';
const SEC_UA = process.env.SEC_USER_AGENT || 'Collective AI ZenFlow Marketplace zenflow-marketplace.vercel.app';
const xml = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: '@' });
// MedlinePlus summaries are entity-heavy HTML; parse without entity expansion and decode the common ones ourselves.
const xmlRaw = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: '@', processEntities: false });
const decode = (t) => String(t || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const MAX_ROWS = 200;

const get = (o, path) => (path ? path.split('.').reduce((v, k) => (v == null ? v : v[k]), o) : o);
const pickFields = (row, fields) => {
  if (!fields) return row;
  const out = {};
  for (const f of fields) { const v = f.includes('.') && !(f in row) ? get(row, f) : row[f]; if (v !== undefined) out[f] = v; }
  return out;
};
const daysAgo = (n) => { const d = new Date(Date.now() - n * 864e5); return d.toISOString().slice(0, 10); };
const ymd = (s) => s.replaceAll('-', '');

async function fetchJson(url, opts = {}, attempt = 0) {
  const r = await fetch(url, { ...opts, redirect: 'follow', signal: AbortSignal.timeout(opts.timeout || 25000), headers: { 'User-Agent': UA, Accept: 'application/json', ...(opts.headers || {}) } });
  const text = await r.text();
  if ((r.status === 429 || r.status === 503) && attempt < 2) { await new Promise((s) => setTimeout(s, 1200 * (attempt + 1))); return fetchJson(url, opts, attempt + 1); }
  if (!r.ok) throw new HttpError(502, 'source_error', `Source returned ${r.status}`, { source_status: r.status, detail: text.slice(0, 300) });
  try { return JSON.parse(text); } catch { throw new HttpError(502, 'source_error', 'Source did not return JSON', { detail: text.slice(0, 200) }); }
}
async function fetchText(url, opts = {}) {
  const r = await fetch(url, { ...opts, redirect: 'follow', signal: AbortSignal.timeout(opts.timeout || 25000), headers: { 'User-Agent': UA, ...(opts.headers || {}) } });
  const text = await r.text();
  if (!r.ok) throw new HttpError(502, 'source_error', `Source returned ${r.status}`, { source_status: r.status, detail: text.slice(0, 300) });
  return text;
}

/** Resolves params: required ones must be present; optional ones fall back to their example. */
export function resolveParams(spec, query) {
  const p = {};
  for (const d of spec.params) {
    let v = query[d.name];
    if (v === undefined || v === '') {
      if (d.required) throw new HttpError(400, 'missing_param', `"${d.name}" is required: ${d.description}`, { example: d.example });
      v = d.example;
    }
    p[d.name] = String(v).slice(0, 300);
  }
  return p;
}

function keyFor(spec, req) {
  const byo = req.headers['x-source-key'];
  if (byo) return String(byo);
  if (spec.key && process.env[spec.key]) return process.env[spec.key];
  if (spec.cfg?.key_default) return spec.cfg.key_default;
  if (spec.cfg?.key_optional) return '';
  if (spec.key) throw new HttpError(503, 'source_key_not_configured', `This source needs ${spec.key}. Set it on the deployment, or send your own as "X-Source-Key".`);
  return '';
}

const fill = (tpl, p, enc = false) => tpl.replace(/\{(\w+)\}/g, (_, k) => (p[k] === undefined ? '' : enc ? encodeURIComponent(p[k]) : p[k]));

function rowsOf(data, items, fields, limit = MAX_ROWS) {
  let rows = items === null || items === undefined ? data : get(data, items);
  if (rows && !Array.isArray(rows)) rows = [rows];
  return (rows || []).slice(0, limit).map((r) => (r && typeof r === 'object' ? pickFields(r, fields) : r));
}

const tableToObjects = (arr) => { const [head, ...rest] = arr || [[]]; return rest.map((r) => Object.fromEntries(head.map((h, i) => [h, r[i]]))); };

async function cikFor(ticker) {
  const t = await fetchJson('https://www.sec.gov/files/company_tickers.json', { headers: { 'User-Agent': SEC_UA } });
  const hit = Object.values(t).find((x) => x.ticker.toUpperCase() === ticker.toUpperCase());
  if (!hit) throw new HttpError(404, 'unknown_ticker', `No SEC registrant for ticker ${ticker}`);
  return { cik: String(hit.cik_str).padStart(10, '0'), name: hit.title };
}

async function pageviewsSeries(article, start, end, granularity = 'daily') {
  const url = `https://wikimedia.org/api/rest_v1/metrics/pageviews/per-article/en.wikipedia/all-access/user/${encodeURIComponent(article.replaceAll(' ', '_'))}/${granularity}/${ymd(start)}00/${ymd(end)}00`;
  const j = await fetchJson(url);
  return (j.items || []).map((i) => ({ date: `${i.timestamp.slice(0, 4)}-${i.timestamp.slice(4, 6)}-${i.timestamp.slice(6, 8)}`, views: i.views }));
}
const pearson = (a, b) => {
  const n = Math.min(a.length, b.length); if (n < 3) return null;
  const ma = a.slice(0, n).reduce((s, x) => s + x, 0) / n, mb = b.slice(0, n).reduce((s, x) => s + x, 0) / n;
  let num = 0, da = 0, db = 0;
  for (let i = 0; i < n; i++) { num += (a[i] - ma) * (b[i] - mb); da += (a[i] - ma) ** 2; db += (b[i] - mb) ** 2; }
  return da && db ? +(num / Math.sqrt(da * db)).toFixed(3) : null;
};

function safeFeedUrl(u) {
  let url;
  try { url = new URL(u); } catch { throw new HttpError(400, 'invalid_url', 'url must be a full https URL'); }
  if (url.protocol !== 'https:') throw new HttpError(400, 'invalid_url', 'Only https feeds are fetched');
  if (/^(localhost|.*\.local|.*\.internal)$/i.test(url.hostname) || /^[\d.]+$/.test(url.hostname) || url.hostname.includes(':')) throw new HttpError(400, 'invalid_url', 'Feeds must be on a public hostname');
  return url.toString();
}

const HANDLERS = {
  async json(spec, p, key) {
    const c = spec.cfg; const all = { ...p, key };
    const url = new URL(fill(c.url, all, true).replaceAll('%2F', '/').replaceAll('..', ''));
    // SoQL / OData filters quote values with single quotes, so escape them in those parameters.
    const soql = Object.fromEntries(Object.entries(all).map(([k, v]) => [k, String(v ?? '').replaceAll("'", "''")]));
    for (const [k, v] of Object.entries(c.query || {})) { const val = fill(v, k.startsWith('$') ? soql : all); if (val !== '' && !/\{\w+\}/.test(val)) url.searchParams.set(k, val); }
    const headers = {};
    for (const [k, v] of Object.entries(c.headers || {})) { if (v.includes('{key}') && !key) continue; headers[k] = fill(v, all); }
    const data = await fetchJson(url.toString(), { headers });
    let src = c.items ? get(data, c.items) : data;
    if (c.flatten && src && !Array.isArray(src)) src = Object.values(src).flat();
    if (c.pivot && src && typeof src === 'object') {
      const byKey = {};
      for (const [series, points] of Object.entries(src)) for (const [k, v] of Object.entries(points || {})) (byKey[k] ??= { period: k })[series] = v;
      src = Object.values(byKey);
    }
    if (c.sort_desc && Array.isArray(src)) src = [...src].sort((a, b) => String(get(b, c.sort_desc) ?? '').localeCompare(String(get(a, c.sort_desc) ?? '')));
    let rows = rowsOf(src, null, c.pick, c.limit);
    if (c.match) for (const [field, tpl] of Object.entries(c.match)) { const want = fill(tpl, all).trim().toLowerCase(); if (want) rows = rows.filter((r) => String(r[field] ?? '').toLowerCase() === want); }
    return { rows };
  },

  async census(spec, p, key) {
    const c = spec.cfg; const url = new URL(c.url);
    url.searchParams.set('get', c.get);
    if (c.time_from) url.searchParams.set('time', `from ${p.from}`);
    if (c.time_param) url.searchParams.set('time', p[c.time_param]);
    for (const [k, v] of Object.entries(c.fixed || {})) url.searchParams.set(k, v);
    for (const [k, v] of Object.entries(c.filters || {})) if (p[v]) url.searchParams.set(k, p[v]);
    if (p.category_code) url.searchParams.set('category_code', p.category_code);
    url.searchParams.set('key', key);
    const data = await fetchJson(url.toString());
    return { rows: tableToObjects(data).slice(-MAX_ROWS) };
  },

  async census_acs(spec, p, key) {
    const url = new URL(`https://api.census.gov/data/${spec.cfg.year}/acs/acs5`);
    url.searchParams.set('get', spec.cfg.vars);
    url.searchParams.set('for', `zip code tabulation area:${p.zip}`);
    url.searchParams.set('key', key);
    const rows = tableToObjects(await fetchJson(url.toString())).map((r) => ({ zcta: r['zip code tabulation area'], name: r.NAME, median_gross_rent_usd: Number(r.B25064_001E), renter_occupied_units: Number(r.B25003_003E) }));
    return { rows };
  },

  async bls(spec, p) {
    const series = (p.series || spec.cfg.default_series).replace(/[^A-Z0-9]/gi, '');
    const j = await fetchJson(`https://api.bls.gov/publicAPI/v1/timeseries/data/${series}`);
    if (j.status !== 'REQUEST_SUCCEEDED') throw new HttpError(502, 'source_error', (j.message || ['BLS request failed']).join(' '));
    const s = j.Results?.series?.[0];
    return { rows: (s?.data || []).map((d) => ({ series: s.seriesID, year: d.year, period: d.period, label: d.periodName, value: Number(d.value) })) };
  },

  async overpass(spec, p) {
    const radius = Math.min(Number(p.radius) || 1500, 5000);
    const q = `[out:json][timeout:20];${fill(spec.cfg.query, { ...p, radius })}`;
    let j, last;
    for (const host of ['https://overpass-api.de/api/interpreter', 'https://overpass.private.coffee/api/interpreter', 'https://maps.mail.ru/osm/tools/overpass/api/interpreter']) {
      try { j = await fetchJson(host, { method: 'POST', body: new URLSearchParams({ data: q }), headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: '*/*' }, timeout: 15000 }); break; } catch (e) { last = e; }
    }
    if (!j) throw last;
    const rows = (j.elements || []).slice(0, MAX_ROWS).map((e) => ({ osm_id: `${e.type}/${e.id}`, lat: e.lat ?? e.center?.lat, lon: e.lon ?? e.center?.lon, name: e.tags?.name, tags: e.tags }));
    const summary = { count: (j.elements || []).length, radius_m: radius };
    if (spec.cfg.summarize) { const by = {}; for (const e of j.elements || []) { const k = e.tags?.[spec.cfg.summarize] || 'unknown'; by[k] = (by[k] || 0) + 1; } summary.by_type = by; }
    return { rows, summary };
  },

  async pageviews(spec, p) {
    const c = spec.cfg; const end = daysAgo(1);
    if (c.mode === 'top') {
      const d = p.date || daysAgo(2);
      const j = await fetchJson(`https://wikimedia.org/api/rest_v1/metrics/pageviews/top/en.wikipedia/all-access/${d.replaceAll('-', '/')}`);
      return { rows: (j.items?.[0]?.articles || []).filter((a) => !/^(Main_Page|Special:|Wikipedia:|Portal:|File:)/.test(a.article)).slice(0, 100) };
    }
    if (c.mode === 'lifespan') {
      const rows = await pageviewsSeries(p.article, '2015-07-01', end, 'monthly');
      const peak = rows.reduce((m, r) => (r.views > (m?.views ?? -1) ? r : m), null);
      const after = peak ? rows.slice(rows.indexOf(peak)) : [];
      const half = after.find((r) => r.views <= peak.views / 2);
      return { rows, summary: { peak_month: peak?.date?.slice(0, 7), peak_views: peak?.views, months_to_half: half ? after.indexOf(half) : null } };
    }
    if (c.mode === 'correlate') {
      const titles = p.articles.split(',').map((s) => s.trim()).filter(Boolean).slice(0, 5);
      if (titles.length < 2) throw new HttpError(400, 'invalid_param', 'Give between 2 and 5 comma-separated articles');
      const series = await Promise.all(titles.map((t) => pageviewsSeries(t, daysAgo(c.days), end)));
      const matrix = titles.map((a, i) => Object.fromEntries(titles.map((b, j) => [b, pearson(series[i].map((x) => x.views), series[j].map((x) => x.views))])));
      return { rows: titles.map((t, i) => ({ article: t, total_views: series[i].reduce((s, x) => s + x.views, 0), correlations: matrix[i] })) };
    }
    const rows = await pageviewsSeries(p.article, daysAgo(c.days || 90), end);
    const summary = { total_views: rows.reduce((s, r) => s + r.views, 0) };
    if (c.drops) {
      const weeks = []; for (let i = 0; i + 7 <= rows.length; i += 7) weeks.push({ week_of: rows[i].date, views: rows.slice(i, i + 7).reduce((s, r) => s + r.views, 0) });
      summary.biggest_drops = weeks.slice(1).map((w, i) => ({ week_of: w.week_of, change: weeks[i].views ? +((w.views - weeks[i].views) / weeks[i].views).toFixed(3) : null })).sort((a, b) => (a.change ?? 0) - (b.change ?? 0)).slice(0, 3);
    }
    return { rows, summary };
  },

  async gdelt(spec, p) {
    const c = spec.cfg;
    const q = `${c.prefix || ''}${p.q ? (/\s/.test(p.q) ? `"${p.q}"` : p.q) : ''}${c.suffix || ''}`.trim();
    const url = new URL('https://api.gdeltproject.org/api/v2/doc/doc');
    url.searchParams.set('query', q); url.searchParams.set('mode', c.mode); url.searchParams.set('format', 'json'); url.searchParams.set('timespan', c.timespan); url.searchParams.set('maxrecords', '75');
    const j = await fetchJson(url.toString(), { timeout: 25000 });
    if (c.mode === 'timelinetone') return { rows: (j.timeline?.[0]?.data || []).map((d) => ({ date: d.date, tone: d.value })) };
    return { rows: (j.articles || []).map((a) => ({ title: a.title, url: a.url, domain: a.domain, seendate: a.seendate, language: a.language, sourcecountry: a.sourcecountry })) };
  },

  async sec_fts(spec, p) {
    const url = new URL('https://efts.sec.gov/LATEST/search-index');
    url.searchParams.set('q', `"${spec.cfg.phrase}"${p.q ? ` "${p.q}"` : ''}`);
    url.searchParams.set('forms', spec.cfg.forms);
    url.searchParams.set('dateRange', 'custom'); url.searchParams.set('startdt', daysAgo(90)); url.searchParams.set('enddt', daysAgo(0));
    const j = await fetchJson(url.toString(), { headers: { 'User-Agent': SEC_UA } });
    return { rows: (j.hits?.hits || []).map((h) => ({ company: (h._source.display_names || [])[0], form: h._source.form, filed: h._source.file_date, items: h._source.items, url: `https://www.sec.gov/Archives/edgar/data/${(h._source.ciks || [''])[0].replace(/^0+/, '')}/${h._id.split(':')[0].replaceAll('-', '')}/${h._id.split(':')[1] || ''}` })) };
  },

  async sec_filings(spec, p) {
    const { cik, name } = await cikFor(p.ticker);
    const j = await fetchJson(`https://data.sec.gov/submissions/CIK${cik}.json`, { headers: { 'User-Agent': SEC_UA } });
    const r = j.filings?.recent || {}; const rows = [];
    for (let i = 0; i < (r.form || []).length && rows.length < 50; i++) {
      if (r.form[i] !== spec.cfg.form) continue;
      const acc = r.accessionNumber[i].replaceAll('-', '');
      rows.push({ company: name, form: r.form[i], filed: r.filingDate[i], report_date: r.reportDate[i], url: `https://www.sec.gov/Archives/edgar/data/${Number(cik)}/${acc}/${r.primaryDocument[i]}` });
    }
    return { rows };
  },

  async sec_xbrl(spec, p) {
    const { cik, name } = await cikFor(p.ticker);
    const j = await fetchJson(`https://data.sec.gov/api/xbrl/companyfacts/CIK${cik}.json`, { headers: { 'User-Agent': SEC_UA } });
    const facts = j.facts?.['us-gaap'] || {}; const rows = [];
    for (const tag of ['Revenues', 'RevenueFromContractWithCustomerExcludingAssessedTax', 'NetIncomeLoss', 'Assets', 'Liabilities', 'CashAndCashEquivalentsAtCarryingValue', 'OperatingIncomeLoss']) {
      const units = facts[tag]?.units?.USD; if (!units) continue;
      const latest = units.filter((u) => /10-[KQ]/.test(u.form)).sort((a, b) => b.end.localeCompare(a.end)).slice(0, 4);
      for (const u of latest) rows.push({ company: name, concept: tag, value_usd: u.val, period_end: u.end, form: u.form, filed: u.filed, fiscal: `${u.fy} ${u.fp}` });
    }
    return { rows };
  },

  async finra_shortvol(spec, p) {
    const sym = p.symbol.toUpperCase();
    for (let back = 1; back <= 7; back++) {
      const d = ymd(daysAgo(back));
      let text;
      try { text = await fetchText(`https://cdn.finra.org/equity/regsho/daily/CNMSshvol${d}.txt`); } catch { continue; }
      const line = text.split('\n').find((l) => l.split('|')[1] === sym);
      if (!line) return { rows: [], summary: { date: d, note: `${sym} not in that day's file` } };
      const [date, symbol, shortVol, exemptVol, totalVol, market] = line.split('|');
      return { rows: [{ date, symbol, short_volume: Number(shortVol), short_exempt_volume: Number(exemptVol), total_volume: Number(totalVol), short_ratio: +(Number(shortVol) / Number(totalVol)).toFixed(4), markets: market?.trim() }] };
    }
    throw new HttpError(502, 'source_error', 'No FINRA short-volume file found for the last 7 days');
  },

  async eth_whales(spec, p) {
    const min = Number(p.min_eth) || 100;
    const j = await fetchJson('https://eth.blockscout.com/api/v2/transactions?filter=validated');
    const rows = (j.items || []).map((t) => ({ hash: t.hash, block: t.block_number ?? t.block, timestamp: t.timestamp, from: t.from?.hash, to: t.to?.hash, value_eth: Number(t.value) / 1e18 })).filter((t) => t.value_eth >= min);
    return { rows, summary: { scanned: (j.items || []).length, min_eth: min } };
  },

  async meta_ads(spec, p, key) {
    const url = new URL('https://graph.facebook.com/v21.0/ads_archive');
    url.searchParams.set('search_terms', p.q); url.searchParams.set('ad_reached_countries', JSON.stringify([p.country.toUpperCase()]));
    url.searchParams.set('ad_type', 'ALL'); url.searchParams.set('limit', '50');
    url.searchParams.set('fields', 'id,page_name,ad_creative_bodies,ad_delivery_start_time,ad_snapshot_url,publisher_platforms');
    url.searchParams.set('access_token', key);
    const j = await fetchJson(url.toString());
    return { rows: j.data || [] };
  },

  async apple_reviews(spec, p) {
    const j = await fetchJson(`https://itunes.apple.com/${encodeURIComponent(p.country)}/rss/customerreviews/page=1/id=${encodeURIComponent(p.app_id)}/sortby=mostrecent/json`);
    const entries = [].concat(j.feed?.entry || []).filter((e) => e['im:rating']);
    return { rows: entries.map((e) => ({ rating: Number(e['im:rating'].label), title: e.title?.label, review: e.content?.label, version: e['im:version']?.label, updated: e.updated?.label })) };
  },

  async cms_provider(spec, p) {
    const url = new URL(`https://data.cms.gov/provider-data/api/1/datastore/query/${spec.cfg.dataset}/0`);
    url.searchParams.set('conditions[0][property]', spec.cfg.filter_property); url.searchParams.set('conditions[0][value]', p.state.toUpperCase()); url.searchParams.set('conditions[0][operator]', '=');
    url.searchParams.set('limit', '100');
    const j = await fetchJson(url.toString());
    return { rows: j.results || [] };
  },

  async eutils(spec, p) {
    const base = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils';
    const api = process.env.NCBI_API_KEY ? `&api_key=${process.env.NCBI_API_KEY}` : '';
    const s = await fetchJson(`${base}/esearch.fcgi?db=${spec.cfg.db}&retmode=json&retmax=20${spec.cfg.sort ? `&sort=${spec.cfg.sort}` : ''}&term=${encodeURIComponent(fill(spec.cfg.term, p))}${api}`);
    const ids = s.esearchresult?.idlist || [];
    if (!ids.length) return { rows: [] };
    const sum = await fetchJson(`${base}/esummary.fcgi?db=${spec.cfg.db}&retmode=json&id=${ids.join(',')}${api}`);
    const res = sum.result || {};
    const rows = ids.map((id) => res[id]).filter(Boolean).map((r) => spec.cfg.db === 'pubmed'
      ? { pmid: r.uid, title: r.title, journal: r.fulljournalname, pubdate: r.pubdate, authors: (r.authors || []).slice(0, 5).map((a) => a.name), url: `https://pubmed.ncbi.nlm.nih.gov/${r.uid}/` }
      : { id: r.uid, title: r.title, accession: r.accession, significance: r.germline_classification?.description ?? r.clinical_significance?.description, review_status: r.germline_classification?.review_status, genes: (r.genes || []).map((g) => g.symbol), url: `https://www.ncbi.nlm.nih.gov/clinvar/variation/${r.uid}/` });
    return { rows };
  },

  async sparql(spec, p) {
    const safe = Object.fromEntries(Object.entries(p).map(([k, v]) => [k, String(v).replace(/["\\{}<>]/g, '')]));
    const url = `https://query.wikidata.org/sparql?format=json&query=${encodeURIComponent(fill(spec.cfg.query, safe))}`;
    const j = await fetchJson(url, { headers: { Accept: 'application/sparql-results+json' }, timeout: 30000 });
    return { rows: (j.results?.bindings || []).map((b) => Object.fromEntries(Object.entries(b).map(([k, v]) => [k, v.value]))) };
  },

  async patentsview(spec, p, key) {
    const q = JSON.stringify({ _text_any: { patent_title: p.q } });
    const f = JSON.stringify(['patent_id', 'patent_title', 'patent_date', 'application.filing_date', 'assignees.assignee_organization']);
    const j = await fetchJson(`https://search.patentsview.org/api/v1/patent/?q=${encodeURIComponent(q)}&f=${encodeURIComponent(f)}&o=${encodeURIComponent('{"size":50}')}`, { headers: { 'X-Api-Key': key } });
    return { rows: (j.patents || []).map((x) => { const filed = x.application?.[0]?.filing_date; const exp = filed ? `${Number(filed.slice(0, 4)) + 20}${filed.slice(4)}` : null; return { patent_id: x.patent_id, title: x.patent_title, granted: x.patent_date, filed, estimated_expiry: exp, assignee: x.assignees?.[0]?.assignee_organization }; }) };
  },

  async courtlistener(spec, p, key) {
    const url = new URL('https://www.courtlistener.com/api/rest/v4/search/');
    url.searchParams.set('q', `${p.q}${spec.cfg.suffix}`); url.searchParams.set('type', spec.cfg.type); url.searchParams.set('order_by', 'score desc');
    const j = await fetchJson(url.toString(), { headers: key ? { Authorization: `Token ${key}` } : {} });
    return { rows: (j.results || []).slice(0, 40).map((r) => ({ case: r.caseName, court: r.court, filed: r.dateFiled, docket: r.docketNumber, judge: r.judge, url: r.absolute_url ? `https://www.courtlistener.com${r.absolute_url}` : r.docket_absolute_url ? `https://www.courtlistener.com${r.docket_absolute_url}` : undefined })) };
  },

  async ofac(spec, p) {
    const text = await fetchText('https://sanctionslistservice.ofac.treas.gov/api/PublicationPreview/exports/SDN.CSV', { timeout: 25000 });
    const needle = p.q.toLowerCase();
    const rows = [];
    for (const line of text.split('\n')) {
      if (!line.toLowerCase().includes(needle)) continue;
      const cols = line.match(/("([^"]|"")*"|[^,]*)(,|$)/g)?.map((c) => c.replace(/,$/, '').replace(/^"|"$/g, '').replaceAll('""', '"')) || [];
      rows.push({ ent_num: cols[0], name: cols[1], type: cols[2] === '-0- ' ? '' : cols[2], program: cols[3], remarks: cols[11]?.slice(0, 400) });
      if (rows.length >= 50) break;
    }
    return { rows, summary: { note: 'A name match is not a determination. A person reviews every hit.' } };
  },

  async wayback(spec, p) {
    const j = await fetchJson(`https://web.archive.org/cdx/search/cdx?url=${encodeURIComponent(p.url)}&output=json&fl=timestamp,digest,statuscode&collapse=digest&filter=statuscode:200&limit=300`, { timeout: 25000 });
    const rows = tableToObjects(j).map((r) => ({ captured: `${r.timestamp.slice(0, 4)}-${r.timestamp.slice(4, 6)}-${r.timestamp.slice(6, 8)}`, content_digest: r.digest, archive_url: `https://web.archive.org/web/${r.timestamp}/${p.url}` }));
    return { rows, summary: { distinct_versions: rows.length } };
  },

  async nasa_fireball(spec, p) {
    const j = await fetchJson(`https://ssd-api.jpl.nasa.gov/fireball.api?limit=${Math.min(Number(p.limit) || 50, 200)}&req-loc=true`);
    return { rows: (j.data || []).map((r) => Object.fromEntries(j.fields.map((f, i) => [f, r[i]]))) };
  },

  async vintage(spec, p) {
    const y = Number(p.year); if (!(y >= 1950 && y < new Date().getFullYear())) throw new HttpError(400, 'invalid_param', 'year must be a past year from 1950');
    const j = await fetchJson(`https://archive-api.open-meteo.com/v1/archive?latitude=${Number(p.lat)}&longitude=${Number(p.lon)}&start_date=${y}-04-01&end_date=${y}-10-31&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&timezone=auto`);
    const d = j.daily || {}; const n = (d.time || []).length;
    const gdd = (d.temperature_2m_max || []).reduce((s, mx, i) => s + Math.max(0, (mx + d.temperature_2m_min[i]) / 2 - 10), 0);
    const months = {};
    (d.time || []).forEach((t, i) => { const m = t.slice(0, 7); months[m] ??= { month: m, avg_max_c: 0, rain_mm: 0, days: 0 }; months[m].avg_max_c += d.temperature_2m_max[i]; months[m].rain_mm += d.precipitation_sum[i] || 0; months[m].days++; });
    return { rows: Object.values(months).map((m) => ({ month: m.month, avg_max_c: +(m.avg_max_c / m.days).toFixed(1), rain_mm: +m.rain_mm.toFixed(1) })), summary: { growing_degree_days_base10: Math.round(gdd), days: n } };
  },

  async opendota(spec, p) {
    const all = await fetchJson('https://api.opendota.com/api/proPlayers', { timeout: 25000 });
    const q = p.q.toLowerCase();
    return { rows: all.filter((x) => `${x.name} ${x.team_name} ${x.personaname}`.toLowerCase().includes(q)).slice(0, 50).map((x) => ({ account_id: x.account_id, name: x.name, team: x.team_name, country: x.country_code, last_match: x.last_match_time })) };
  },

  async hf_rows(spec, p) {
    const len = Math.min(Number(p.length) || 20, 100), off = Math.max(Number(p.offset) || 0, 0);
    const c = spec.cfg;
    const j = await fetchJson(`https://datasets-server.huggingface.co/rows?dataset=${encodeURIComponent(c.dataset)}&config=${encodeURIComponent(c.config)}&split=${encodeURIComponent(c.split)}&offset=${off}&length=${len}`, { timeout: 25000 });
    return { rows: (j.rows || []).map((r) => r.row), summary: { total_rows: j.num_rows_total, dataset: c.dataset } };
  },

  async hn_velocity(spec, p) {
    const since = Math.floor((Date.now() - 30 * 864e5) / 1000);
    const j = await fetchJson(`https://hn.algolia.com/api/v1/search_by_date?query=${encodeURIComponent(p.q)}&tags=story&numericFilters=created_at_i>${since}&hitsPerPage=1000`);
    const by = {}; for (const h of j.hits || []) { const d = h.created_at.slice(0, 10); by[d] = (by[d] || 0) + 1; }
    return { rows: Object.entries(by).sort().map(([date, stories]) => ({ date, stories })), summary: { stories_30d: j.nbHits, top: (j.hits || []).sort((a, b) => (b.points || 0) - (a.points || 0)).slice(0, 5).map((h) => ({ title: h.title, points: h.points, url: `https://news.ycombinator.com/item?id=${h.objectID}` })) } };
  },

  async feed(spec, p) {
    const text = await fetchText(safeFeedUrl(p.url), { headers: { Accept: 'application/rss+xml, application/atom+xml, application/xml' } });
    const doc = xml.parse(text);
    const items = [].concat(doc.rss?.channel?.item || doc.feed?.entry || []);
    const rows = items.slice(0, 100).map((i) => ({ title: typeof i.title === 'object' ? i.title['#text'] : i.title, link: typeof i.link === 'object' ? (i.link['@href'] || [].concat(i.link)[0]?.['@href']) : i.link, published: i.pubDate || i.published || i.updated }));
    const dates = rows.map((r) => Date.parse(r.published)).filter(Boolean).sort((a, b) => b - a);
    const weeks = dates.length > 1 ? (dates[0] - dates[dates.length - 1]) / (7 * 864e5) : 0;
    return { rows, summary: { posts: rows.length, posts_per_week: weeks ? +(rows.length / weeks).toFixed(2) : null } };
  },

  async twitch(spec, p, key, req) {
    const id = req.headers['x-source-client-id'] || process.env.TWITCH_CLIENT_ID; const secret = req.headers['x-source-key'] || process.env.TWITCH_CLIENT_SECRET;
    if (!id || !secret) throw new HttpError(503, 'source_key_not_configured', 'Needs TWITCH_CLIENT_ID and TWITCH_CLIENT_SECRET (or X-Source-Client-Id and X-Source-Key)');
    const tok = await fetchJson(`https://id.twitch.tv/oauth2/token?client_id=${encodeURIComponent(id)}&client_secret=${encodeURIComponent(secret)}&grant_type=client_credentials`, { method: 'POST' });
    const url = new URL('https://api.twitch.tv/helix/streams'); url.searchParams.set('first', '50');
    if (p.login) url.searchParams.set('user_login', p.login); if (p.game_id) url.searchParams.set('game_id', p.game_id);
    const j = await fetchJson(url.toString(), { headers: { 'Client-Id': id, Authorization: `Bearer ${tok.access_token}` } });
    return { rows: (j.data || []).map((s) => ({ user: s.user_name, game: s.game_name, title: s.title, viewers: s.viewer_count, started: s.started_at, language: s.language })) };
  },

  async faa_status() {
    const doc = xml.parse(await fetchText('https://nasstatus.faa.gov/api/airport-status-information'));
    const lists = [].concat(doc.AIRPORT_STATUS_INFORMATION?.Delay_type || []);
    const rows = [];
    for (const d of lists) {
      const name = d.Name;
      for (const prog of [].concat(d.Ground_Delay_List?.Ground_Delay || [], d.Ground_Stop_List?.Program || [], d.Arrival_Departure_Delay_List?.Delay || [], d.Airport_Closure_List?.Airport || [])) {
        rows.push({ type: name, airport: prog.ARPT || prog.Arpt || prog.ARPT_ID, reason: prog.Reason || prog.Reason_Text, average: prog.Avg, max: prog.Max, until: prog.End_Time || prog.Reopen });
      }
    }
    return { rows, summary: { updated: doc.AIRPORT_STATUS_INFORMATION?.Update_Time } };
  },

  async ecfr(spec, p) {
    const url = new URL('https://www.ecfr.gov/api/search/v1/results');
    url.searchParams.set('query', p.q); url.searchParams.set('per_page', '15');
    if (spec.cfg.title) url.searchParams.set('hierarchy[title]', spec.cfg.title);
    const j = await fetchJson(url.toString());
    return { rows: (j.results || []).map((r) => ({ citation: `${r.hierarchy?.title} CFR ${r.hierarchy?.section || r.hierarchy?.part}`, heading: r.headings?.section || r.headings?.part, passage: String(r.full_text_excerpt || '').replace(/<[^>]+>/g, ''), url: r.hierarchy?.section ? `https://www.ecfr.gov/current/title-${r.hierarchy.title}/section-${r.hierarchy.section}` : undefined })) };
  },

  async medlineplus(spec, p) {
    const doc = xmlRaw.parse(await fetchText(`https://wsearch.nlm.nih.gov/ws/query?db=healthTopics&term=${encodeURIComponent(p.q)}&retmax=10`));
    const docs = [].concat(doc.nlmSearchResult?.list?.document || []);
    const field = (d, name) => [].concat(d.content || []).find((c) => c['@name'] === name)?.['#text'];
    const clean = (t) => decode(decode(t)).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
    return { rows: docs.map((d) => ({ title: clean(field(d, 'title')), passage: clean(field(d, 'FullSummary') || field(d, 'snippet')).slice(0, 1500), url: decode(d['@url']) })) };
  },

  async arxiv(spec, p) {
    const doc = xml.parse(await fetchText(`https://export.arxiv.org/api/query?search_query=all:${encodeURIComponent(p.q)}&max_results=20&sortBy=relevance`));
    return { rows: [].concat(doc.feed?.entry || []).map((e) => ({ title: String(e.title).replace(/\s+/g, ' ').trim(), authors: [].concat(e.author || []).slice(0, 6).map((a) => a.name), published: e.published, passage: String(e.summary).replace(/\s+/g, ' ').trim(), url: e.id, pdf: [].concat(e.link || []).find((l) => l['@title'] === 'pdf')?.['@href'] })) };
  },

  async wikivoyage(spec, p) {
    const j = await fetchJson(`https://en.wikivoyage.org/w/api.php?action=query&generator=search&gsrsearch=${encodeURIComponent(p.q)}&gsrlimit=8&prop=extracts&exintro=1&explaintext=1&format=json&formatversion=2`);
    return { rows: (j.query?.pages || []).sort((a, b) => a.index - b.index).map((pg) => ({ title: pg.title, passage: (pg.extract || '').slice(0, 1500), url: `https://en.wikivoyage.org/wiki/${encodeURIComponent(pg.title.replaceAll(' ', '_'))}` })) };
  },
};

export async function queryDataset(id, spec, req) {
  const handler = HANDLERS[spec.handler];
  if (!handler) throw new HttpError(500, 'no_connector', `No connector for ${id}`);
  const p = resolveParams(spec, req.zfQuery || {});
  const key = keyFor(spec, req);
  const started = Date.now();
  const out = await handler(spec, p, key, req);
  return { params: p, latency: Date.now() - started, ...out };
}

export const CONNECTORS = Object.keys(HANDLERS);
